node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// Build a comprehensive report
const lines = [];

// Header
lines.push('========================================================');
lines.push('  Retail CS Report — Return Policy Context');
lines.push('  Generated from world.db');
lines.push('========================================================');
lines.push('');

// Context
const meta = db.prepare('SELECT * FROM world_meta').all();
lines.push('Context:');
meta.forEach(m => lines.push('  ' + m.key + ': ' + m.value));
lines.push('');

// Return-requested orders
lines.push('--------------------------------------------------------');
lines.push('  Orders with Return Requested');
lines.push('--------------------------------------------------------');
const returnOrders = db.prepare(\"SELECT * FROM orders WHERE source_skill = 'tau2Retail' AND status = 'return requested'\").all();
if (returnOrders.length === 0) {
  lines.push('  (none)');
} else {
  returnOrders.forEach(o => {
    lines.push('');
    lines.push('  Order: ' + o.order_id);
    lines.push('  Customer: ' + o.customer_id);
    lines.push('  Status: ' + o.status);
    lines.push('  Return Items: ' + o.return_items);
    lines.push('  Refund Method: ' + o.return_payment_method_id);
    const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(o.order_id);
    lines.push('  Order Items:');
    items.forEach(i => {
      lines.push('    - ' + i.name + ' | item_id: ' + i.item_id + ' | price: \$' + i.unit_price.toFixed(2));
    });
    const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(o.order_id);
    lines.push('  Payment History:');
    payments.forEach(p => {
      lines.push('    - ' + p.transaction_type + ': \$' + p.amount.toFixed(2) + ' via ' + p.payment_method_id);
    });
  });
}
lines.push('');

// Delivered orders (eligible for return)
lines.push('--------------------------------------------------------');
lines.push('  Delivered Orders (Eligible for Return)');
lines.push('--------------------------------------------------------');
const delivered = db.prepare(\"SELECT * FROM orders WHERE source_skill = 'tau2Retail' AND status = 'delivered'\").all();
delivered.forEach(o => {
  lines.push('');
  lines.push('  Order: ' + o.order_id + ' | Customer: ' + o.customer_id);
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(o.order_id);
  items.forEach(i => {
    lines.push('    - ' + i.name + ' | item_id: ' + i.item_id + ' | price: \$' + i.unit_price.toFixed(2));
  });
  const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all(o.order_id);
  lines.push('  Payment:');
  payments.forEach(p => {
    lines.push('    - ' + p.transaction_type + ': \$' + p.amount.toFixed(2) + ' via ' + p.payment_method_id);
  });
});
lines.push('');

// Summary stats
lines.push('--------------------------------------------------------');
lines.push('  Summary');
lines.push('--------------------------------------------------------');
const allOrders = db.prepare(\"SELECT status, COUNT(*) as cnt FROM orders WHERE source_skill = 'tau2Retail' GROUP BY status\").all();
lines.push('  Order counts by status:');
allOrders.forEach(r => {
  lines.push('    ' + r.status + ': ' + r.cnt);
});
lines.push('');
lines.push('  Total delivered (return-eligible): ' + delivered.length);
lines.push('  Total return requested: ' + returnOrders.length);

let returnTotal = 0;
returnOrders.forEach(o => {
  const returnItemIds = JSON.parse(o.return_items || '[]');
  const items = db.prepare('SELECT * FROM order_items WHERE order_id = ?').all(o.order_id);
  items.forEach(i => {
    if (returnItemIds.includes(i.item_id)) {
      returnTotal += i.unit_price;
    }
  });
});
lines.push('  Total return value pending: \$' + returnTotal.toFixed(2));
lines.push('');
lines.push('========================================================');

const output = lines.join('\n');
console.log(output);
" > /workspace/return_policy_report.txt
